from playwright.sync_api import sync_playwright
with sync_playwright() as p:
 b=p.chromium.launch(executable_path='/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',headless=True)
 page=b.new_page(viewport={'width':360,'height':768});page.add_init_script("window.addEventListener('error',e=>{if(e.message.includes('ResizeObserver loop'))e.stopImmediatePropagation();});");page.set_default_timeout(8000);page.goto('http://127.0.0.1:4173/?workspace=responsive',wait_until='networkidle')
 page.get_by_role('button',name='Lainnya').click();page.get_by_role('button',name='Pengaturan',exact=True).click();button=page.get_by_role('button',name='Data & Perangkat',exact=True);page.evaluate('window.scrollTo(0,document.body.scrollHeight)');page.wait_for_timeout(200);button.scroll_into_view_if_needed();before=page.evaluate('scrollY');button.click();page.get_by_role('button',name='Kembali ke pengaturan').click();page.wait_for_timeout(200);after=page.evaluate('scrollY');assert abs(after-before)<5,(before,after)
 print('360 posisi daftar pengaturan dipertahankan',flush=True);page.close()
 page=b.new_page(viewport={'width':1024,'height':768});page.add_init_script("window.addEventListener('error',e=>{if(e.message.includes('ResizeObserver loop'))e.stopImmediatePropagation();});");page.set_default_timeout(8000);page.goto('http://127.0.0.1:4173/?workspace=responsive',wait_until='networkidle');page.get_by_role('button',name='Panel review').click();page.get_by_label('Perangkat contoh').click();page.get_by_role('option',name='HP owner').click();page.get_by_role('button',name='Tutup panel review').click();page.get_by_role('button',name='Kelola toko').click();page.get_by_role('button',name='Pengaturan',exact=True).click();page.get_by_role('button',name='Edit',exact=True).click();page.get_by_label('Nama toko').fill('Tidak berlaku');page.get_by_role('button',name='Simpan',exact=True).click();page.get_by_text('HP owner hanya meninjau',exact=False).wait_for();assert page.get_by_label('Nama toko').input_value()=='Tidak berlaku'
 print('HP owner tidak menjalankan mutasi pengaturan',flush=True);page.close();b.close()
